@startuml

class HospitalHouseMD {
  + name : string
}

class Patient {
  + name : string
  + symptoms : string
}

class Doctor {
  + name : string
  + practitionerNumber : int
}

class HeadDoctor {
  + name : string
}

class Diagnosis {
  + description : string
  + date : date
}

class Treatment {
  + name : string
  + description : string
}

class TreatmentStage {
  + level : int
}

enum PriorityScore {
  High
  Low
}

class Illness {
  + name : string
  + priority : PriorityScore
}

class ConsentForm {
  + signature : string
  + dateSigned : date
  + dateRetracted : date
}

class TreatmentRecord {
  + startTime : datetime
  + endTime : datetime
}

HospitalHouseMD "1" o-- "1..*" Patient
Patient "1" -- "1..*" Doctor
Doctor "1" -- "1..*" Diagnosis
HeadDoctor "1" -- "0..*" Diagnosis : approves
Diagnosis "1" -- "1" Illness
Illness "1" -- "0..*" Treatment
Diagnosis "1" -- "1..*" TreatmentRecord
Treatment "1" -- "1" TreatmentStage
TreatmentRecord "1" -- "1" TreatmentStage
Patient "1" -- "0..*" ConsentForm
ConsentForm "1" -- "0..*" TreatmentRecord
Doctor "1" -- "0..*" TreatmentRecord : manages_downgrade

@enduml

